def cns(ts, s):
	if ts / s == int(ts / s):
		return ts
	else:
		return (int(ts / s) + 1) * s
(n, spp) = [int(i) for i in input().split()]
tsr = 0
da = [[] for i in range(100005)]
db = [[] for i in range(100005)]
sl = []
for i in range(n):
	sl.append([int(j) for j in input().split()])
	tsr += sl[i][0]
	if sl[i][1] > sl[i][2]:
		da[sl[i][1] - sl[i][2]].append(i)
	else:
		db[sl[i][2] - sl[i][1]].append(i)
tsa = cns(tsr, spp)
a1 = 0
c1 = 0
for i in range(100000, -1, -1):
	for j in da[i]:
		a1 += sl[j][0] * sl[j][1]
		c1 += sl[j][0]
c1r = cns(c1, spp) - c1
c2r = tsa - cns(c1, spp)
for i in range(100000, -1, -1):
	for j in db[i]:
		if sl[j][0] > c2r:
			a1 += c2r * sl[j][2]
			a1 += (sl[j][0] - c2r) * sl[j][1]
			c2r = 0
		else:
			a1 += sl[j][0] * sl[j][2]
			c2r -= sl[j][0]
a2 = 0
c2 = 0
for i in range(100000, -1, -1):
	for j in db[i]:
		a2 += sl[j][0] * sl[j][2]
		c2 += sl[j][0]
c2r = cns(c2, spp) - c2
c1r = tsa - cns(c2, spp)
for i in range(100000, -1, -1):
	for j in da[i]:
		if sl[j][0] > c1r:
			a2 += c1r * sl[j][1]
			a2 += (sl[j][0] - c1r) * sl[j][2]
			c1r = 0
		else:
			a2 += sl[j][0] * sl[j][1]
			c1r -= sl[j][0]
print(max(a1, a2))
